const id=location.pathname.match(/^\/g\/([a-f0-9]{32})$/)?.[1],status=document.querySelector('.present-status'),frame=document.querySelector('iframe');
async function api(path,{method='GET',body,secret}={}){const response=await fetch(path,{method,headers:{...(secret?{Authorization:'Bearer '+secret}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível abrir agora.');return data;}
async function open(){if(!id)throw Error('O endereço deste presente está incompleto.');const data=await api('/api/presents/'+id);document.querySelector('h1').textContent=data.recipient?'Um mimo para '+data.recipient+'.':'Tem um mimo para você.';status.textContent='Abra, aproxime e leia no seu ritmo.';document.querySelector('.test-notice').hidden=!data.test;frame.src='/api/presents/'+id+'/content';frame.hidden=false;document.querySelector('.present-actions').hidden=false;document.querySelector('.present-download').href='/api/presents/'+id+'/download';document.querySelector('.present-fullscreen').addEventListener('click',async()=>{try{await frame.requestFullscreen();}catch{frame.scrollIntoView({behavior:'smooth',block:'start'});}});
 const guestId=new URLSearchParams(location.search).get('convidado'),secret=new URLSearchParams(location.hash.slice(1)).get('responder');if(data.rsvp&&/^[a-f0-9]{32}$/.test(guestId||'')&&/^[a-f0-9]{64}$/.test(secret||'')){
  const path='/api/presents/'+id+'/guests/'+guestId,guest=await api(path,{secret}),section=document.querySelector('.rsvp'),form=section.querySelector('form');section.hidden=false;section.querySelector('.guest-name').textContent='Este convite é para '+guest.name+'.';form.elements.count.max=guest.allowedCount;form.elements.count.value=guest.attendingCount||1;form.elements.status.value=guest.status==='declined'?'declined':'accepted';const update=()=>section.querySelector('.attending-label').hidden=form.elements.status.value==='declined';form.elements.status.addEventListener('change',update);update();if(guest.status!=='invited')section.querySelector('.rsvp-status').textContent='Sua resposta já está salva. Você pode atualizá-la.';form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const result=await api(path,{method:'PUT',secret,body:{status:form.elements.status.value,attendingCount:Number(form.elements.count.value)}});section.querySelector('.rsvp-status').textContent=result.status==='accepted'?'Presença confirmada! Sua resposta foi recebida.':'Resposta recebida. Obrigado por avisar.';}catch(e){section.querySelector('.rsvp-status').textContent=e.message;}finally{button.disabled=false;}});
 }
}
open().catch(e=>{status.textContent=e.message;document.querySelector('.access-note').textContent='Confira o endereço ou fale com quem enviou o mimo.';});
